# Uncertainty of the official training-only backtest numbers (saved predictions of backtest-mode trials).
import glob, json, numpy as np, pandas as pd
from sklearn.metrics import roc_auc_score
R='/Users/earino/research/factory-prospective-study/.local/studies/fra-form54-hazmat-release-retry-1/.study/runs/fra-form54-hazmat-release--r1/'
ids={'H2':'057c5c1c','H4':'ee67241b','H5':'a79214a0','H6':'05efcec8','A1':'6428e69d','A2':'faa42ff4','H7':'1dba3217','H8':'7799dc99'}
P={}
for k,t in ids.items():
    d=[x for x in glob.glob(R+'trials/*/') if t in x][0]; f=pd.read_csv(d+'validation.csv.gz'); P[k]=f.p.to_numpy(); y=f.y.to_numpy()
print('backtest scoring rows',len(y),'positives',int(y.sum()))
rng=np.random.RandomState(0); idx=[rng.randint(0,len(y),len(y)) for _ in range(2000)]
B={k:np.array([roc_auc_score(y[i],p[i]) for i in idx]) for k,p in P.items()}
for k in ids: print(f'{k}: backtest AUC {roc_auc_score(y,P[k]):.4f}  95% CI [{np.percentile(B[k],2.5):.3f}, {np.percentile(B[k],97.5):.3f}]')
for a,b in (('H8','H6'),('H8','H7'),('H7','H6'),('A1','H6'),('H8','H2')):
    d=B[a]-B[b]; print(f'{a} - {b}: {d.mean():+.4f} [{np.percentile(d,2.5):+.4f}, {np.percentile(d,97.5):+.4f}] P(>0)={np.mean(d>0):.3f}')
EOF
